package com.kaymlyn.planeteater.simulation.physics;

/**
 * REFACTORED: PiecewiseState with absolute time semantics
 *
 * Represents the state of a spacecraft at a point in its trajectory.
 *
 * KEY CHANGE: Field renamed from "timeElapsed" to "absoluteTime" to eliminate
 * any ambiguity. This is NOT "time since X" - it's the actual simulation time
 * from OrbitalSystem.getCurrentTime().
 *
 * Generated by Claude (Sonnet 4.5) - Absolute Time Refactor
 *
 * @param id Identifier for this state (e.g., "Coast @t=5400.0")
 * @param position Position vector in meters
 * @param velocity Velocity vector in m/s
 * @param absoluteTime Absolute simulation time in seconds (NOT relative offset)
 * @param fractionComplete Progress through maneuver (0.0 to 1.0)
 */
public record PiecewiseState(
        String id,
        Vector3D position,
        Vector3D velocity,
        double absoluteTime,      // RENAMED from "timeElapsed"
        double fractionComplete
) {

    @Override
    public String toString() {
        return String.format("State[pos=%s, vel=%s, t=%.1f s, progress=%.1f%%]",
                position, velocity, absoluteTime, fractionComplete * 100);
    }
}